def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    dr,dc=1,1
    for r,c in [(0,0),(0,w-1),(h-1,0),(h-1,w-1)]:
        if grid[r][c]==4:
            dr=1 if r==0 else -1
            dc=1 if c==0 else -1
            break
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (bg,4):
                y,x=r+dr,c+dc
                while 0<=y<h and 0<=x<w and grid[y][x]==bg:
                    out[y][x]=0
                    y+=dr
                    x+=dc
    return out

